-- ----------------------------
-- Records of db_flower
-- ----------------------------
INSERT INTO `db_flower` VALUES ('1', '0001', '虹之玉', '5.80', '虹之玉（Sedum x rubrotinctum Clausen [1]  ）是景天科景天属的多肉植物，多年生肉质草本植物。生长速度比较快，春夏是主要生长季节，夏季35度高温需遮阴。\r\n冬天保持5摄氏度以上即可安全越冬。该品种为人工杂交种。', '红颜知己，心心相通');
INSERT INTO `db_flower` VALUES ('2', '0002', '熊童子', '14.30', '熊童子（学名：Cotyledon tomentosa Harv.）是景天科，银波锦属的多年生肉质草本植物，植株多分枝，茎绿色，肉质叶肥厚，交互对生，卵圆形，绿色，密生白色短毛。叶端具红色爪样齿，二歧聚伞花序，小花黄色，花期7-9月。\r\n该种原产于南非开普省。喜温暖干燥，阳光充足，通风良好的环境。夏季温度过高会休眠。忌寒冷和过分潮湿。繁殖方法有扦插。\r\n该种叶形叶色较美，花朵玲珑小巧，叶片形似小熊的脚掌，形态奇特，十分可爱，观赏价值很高。', '玲珑优雅、绿色山珍');
INSERT INTO `db_flower` VALUES ('3', '0003', '黑法师', '4.90', '黑法师是景天科莲花掌属的栽培品种，自然界不存在分布。紫黑色的叶片呈莲座状层叠排列，给人以庄重神秘之感，观赏价值高。宜用排水透气良好的介质种植。', '庄严、美丽、神秘');
INSERT INTO `db_flower` VALUES ('4', '0004', '金琥', '6.90', '金琥（学名：Echinocactus grusonii Hildm.）是仙人掌科、金琥属多年生草本多浆植物。茎圆球形，肉质。植株球体高可达1.3米，植株生长缓慢，球体上有棱沟宽且深，排列菲常整齐。密生金黄色扁平俋刺，辐射刺球顶部密被金黄色绵毛。花着生球茎顶部，钟形，花筒被尖鳞片。果被鳞片，6-10月开花。\r\n该种原产墨西哥中部炎热干燥的沙漠地区，中国有引种，各地广泛栽培。适生海拔高，阳光充足，冬季气候温和。\r\n野生的金琥是极度濒危的稀有植物。金琥球体浑圆碧绿，刺色金黄，刚硬有力，为强刺类品种的代表种。盆栽可长成规整的大型标本球，点缀厅堂，更显金碧辉煌，为室内盆栽植物中的佳品。', '坚强，将爱情进行到底');
INSERT INTO `db_flower` VALUES ('5', '0005', '玉扇', '28.80', '玉扇（Haworthia truncata Schönland） [1]  又名截形瓦苇、截形十二卷，是阿福花科，瓦苇属的多年生草本植物。 [2]  植株无茎，肉质叶排成两列呈扇形，叶片直立，稍向内弯，顶部略凹陷。叶表粗糙，绿色至暗绿褐色，有小疣状突起；新叶的截面部分透明，呈灰白色。习性强健，根系比较粗壮。有些品种叶片截面上还有灰白色透明状花纹。其园艺品种玉扇锦叶片上有黄色或粉红色斑纹。\r\n该种喜凉爽、充足而柔和的阳光。耐干旱与半阴，忌阴湿，不耐寒，怕高温。繁殖方法有叶插、分株等。\r\n玉扇形态奇特，叶色美丽，是一种珍奇的观赏花卉品种。', '开朗、活泼');
INSERT INTO `db_flower` VALUES ('6', '0006', '火祭', '3.00', '火祭，别名秋火莲，为景天科、青锁龙属多年生草本植物。茎匍伏或直立。植株丛生，肉质叶交互对生，正常生长情况下排列紧密，整株呈四棱状。性喜阳光充足且较为干燥的生长环境。叶片在阳光充足环境下呈浅绿色至鲜红色。', '热烈');
INSERT INTO `db_flower` VALUES ('7', '0007', '黄丽', '7.90', '黄丽是景天科景天属多肉，春秋季是其生长旺盛期。\r\n黄丽原产自墨西哥，喜欢温暖、干燥环境，最适宜的生长温度为18~25℃。\r\n黄丽的生长需要充足的阳光，亦可耐半阴，但避免强光直射，湿度的光照下，叶中为绿色，叶尖为黄色。\r\n黄丽常见的繁殖方法：分株、扦插、叶插。', '1.欢快愉悦\r\n2.顽强、富贵、永恒、永不凋谢的爱');
INSERT INTO `db_flower` VALUES ('8', '0008', '不夜城芦荟', '8.80', '不夜城芦荟（学名：Aloe nobilis）又名不夜城、大翠盘、高尚芦荟，是百合科芦荟属的多年生肉质植物，冬末至早春开花。属多年生肉质草本植物，植株单生或丛生。\r\n不夜城芦荟还有一个斑锦变异变种，称“不夜城锦”，叶面及叶背均有黄色或黄白色纵条纹，其条纹的宽窄因植株而异，有时整个叶子都呈黄色。其余特征与不夜城芦荟相同，经常做家用观赏植物。', '夜色中的迷离舞者');
INSERT INTO `db_flower` VALUES ('9', '0009', '八千代', '22.00', '八千代（Sedum corynephyllum）是景天科景天属多年生肉质植物。其原产于墨西哥，喜温暖、干燥和阳光充足的环境，不耐寒，怕水湿。出状态后，叶尖顶端呈红色。', '坚强');
INSERT INTO `db_flower` VALUES ('10', '0010', '乙女心', '10.90', '乙女心（Sedum pachyphyllum Rose）是景天科景天属的多肉植物，原产墨西哥。 [1]  多年生亚灌木，茎叶肉质，株高5-30厘米。叶片簇生于茎顶，圆柱状，淡绿色或淡灰蓝色，叶先端具红色，叶长3~4厘米。花小，黄色。春秋为生长季，冬季气温保持在五度左右可安全越冬。', '活泼、青春');
INSERT INTO `db_flower` VALUES ('11', '0011', '碧光环', '5.55', '碧光环（学名：Monilaria obconica Ihlenf. & Joergens.）是番杏科，碧光环属多年生肉质草本，原生地位于南非。生长适温为15~25摄氏度，夏季温度超过35摄氏度时叶片慢慢枯萎，进入休眠；气温下降后，逐渐恢复浇水即可使其恢复生长。可通过播种和分株繁殖。', '可爱');
INSERT INTO `db_flower` VALUES ('12', '0012', '吉娃莲', '1.90', '吉娃莲，景天科拟石莲花属，别名：吉娃娃（因为常与狗名混淆，所以大多数情况只叫吉娃莲）， [1]  原产于墨西哥奇瓦瓦州，生长在空气流通较好、日照充分的山坡上。吉娃莲，植株小型，无茎的莲座叶盘非常紧凑。卵形叶较厚，带小尖，蓝绿色被浓厚的白粉，叶缘为美丽的深粉红色。花序先端弯曲，钟状，红色。栽培不太困难，夏天不能浇过多的水。叶尖的红色特别美丽，是一种观赏性很强的多肉植物。', '纯洁高雅与珍爱之意');
INSERT INTO `db_flower` VALUES ('13', '0013', '姬玉露', '2.60', '姬玉露（学名：Haworthia cooperi var. truncata (H.Jacobsen) M.B.Bayer）是阿福花科，十二卷属的多年生草本。植株无茎，初为单生，后逐渐呈群生状；叶绿色，肉质，上半段呈透明或半透明状，称为“窗”，用于光合作用。总状花序，小花白色。\r\n原产南非，喜凉爽微潮和阳光散射的环境。耐干旱，怕高温潮湿。要求疏松、颗粒较多的沙壤土地。养护最佳温度不应低于20℃。繁殖方法有分株、叶插、播种等。\r\n其叶形叶色较美，形态奇特，晶莹剔透，观赏价值很高，常被用于制作多肉植物盆栽。', '冰清玉洁');
INSERT INTO `db_flower` VALUES ('14', '0014', '薄雪万年草', '6.80', '薄雪万年草 [1]  ，学名：Sedum hispanicum，景天科景天属的多年生草本植物，广布南欧至中亚地区。原产西班牙，也叫矶小松。\r\n怕热耐寒。根是须根性，茎匍匐生长，叶棒状密集，开花。', '活泼、青春');
INSERT INTO `db_flower` VALUES ('15', '0015', '条纹蛇尾兰', '3.00', '条纹蛇尾兰，又名条纹十二卷、锦鸡尾（学名：Haworthia fasciata ），是阿福花科十二卷属 [1]  多年生肉质草本植物，叶片紧密轮生在茎轴上，呈莲座状；叶三角状披针形，先端锐尖；叶表光滑，深绿色；叶背绿色，具较大的白色瘤状突起，这些突起排列成横条纹，与叶面的深绿色形成鲜明的对比。具有较好的观赏价值。原生地位于非洲南部热带干旱地区。喜欢在阳光充足的环境，生长适温为16～20℃，耐干旱，要求排水良好营养丰富的土壤。', '活泼、青春');
INSERT INTO `db_flower` VALUES ('16', '0016', '筒叶花月', '14.90', '筒叶花月是以观叶为主的多肉植物，叶片翠绿，四季常青，多作办公室、居室、 阳台的摆件，也有少量用来制作多肉盆景，是一款很普及的多肉精品。', '升官发财');
INSERT INTO `db_flower` VALUES ('17', '0017', '茜之塔', '10.80', '茜之塔（学名：Crassula ‘Pagoda Village’）是景天科、青锁龙属的多年生肉质草本植物，是多肉植物的一种。矮小的植株呈丛生状，高仅5～8厘米。直立生长，多年生植株匍匐。中文名中的“茜”指的是其叶片的深红色；整齐层叠的紫红色叶片令人联想到具有东方特色的红色佛塔，因此得名。', '优雅、浪漫');
INSERT INTO `db_flower` VALUES ('18', '0018', '金钱木', '2.80', '金钱木（学名：Portulaca molokiniensis Hobdy）是马齿苋属多年生常绿草本植物，金钱木地上部无主茎，不定芽从块茎萌发形成大型复叶，小叶肉质具，坚挺浓绿；地下部分为肥大的块茎。根出叶，叶柄基部膨大，木质化；每枚复叶有小叶6-10对，具2-3年以上寿命。\r\n因肥厚的叶片排列整齐酷似铜钱而得名，是优良室内观叶植物。\r\n金钱木喜阳光充足和温暖、干燥的环境，耐干旱，忌阴湿和寒冷。', '富贵吉祥');
INSERT INTO `db_flower` VALUES ('19', '0019', '玉龙观音', '13.40', '玉龙观音Aeonium holochrysum是景天科莲花掌属的多肉植物、 [1]  也称多浆植物，属于莲花掌属中的巨无霸，叶片有香味，日照充分的情况下叶片的香味会更浓。', '平安祥和');
INSERT INTO `db_flower` VALUES ('20', '0020', '春兰', '18.00', '根肉质、白色。叶狭线形，长约20厘米一25厘米，边缘具有细锐锯齿，叶脉明显。每茎1～2朵花，黄绿色，香味清幽。早春2～3月开花。品种繁多，通常依花瓣的形状分为梅花瓣、水仙瓣、荷花瓣、蝴蝶瓣、素心瓣等型。名贵的品种有小打梅、宋梅、绿云、汪字、郑同荷等。', '高洁、高雅、美好、贤德、淡泊');
INSERT INTO `db_flower` VALUES ('21', '0021', '蕙兰', '20.00', '根肉质、淡黄色，叶线形，比春兰直立而粗长，叶缘粗糙。一茎着花5～13朵，淡黄色，唇瓣绿白色，具红紫斑点。花甚香，花期4—5月。名贵品种有程梅、送春、荡字、隆昌素等。', '高洁、高雅、美好、贤德、淡泊');
INSERT INTO `db_flower` VALUES ('22', '0022', '建兰', '19.80', '叶阔线形，长30厘米～60厘米，多直立，叶缘光滑。一茎着花6～12朵。花黄绿色乃至淡黄褐色，有暗紫色条纹。香味甚浓，花期7～9月。名贵品种有十三太保、龙岩素心、铁骨素、银边大贡等。', '高洁、高雅、美好、贤德、淡泊');
INSERT INTO `db_flower` VALUES ('23', '0023', '墨兰', '22.15', '叶长50厘米一100厘米，宽达3厘米，光滑，先端尖，直立性。花茎高约60厘米，一茎着花5一’10朵，花瓣多具紫褐条纹。花期冬季至早春，有香味。名贵品种有绿墨、白墨、鹦鹉墨、徽州墨等。', '高洁、高雅、美好、贤德、淡泊');
INSERT INTO `db_flower` VALUES ('24', '0024', '文心兰', '12.00', '常被称为跳舞兰、金蝶兰、瘤瓣兰等，兰科文心兰属植物的总称。文心兰是一种极美丽而又极具观赏价值的兰花，是世界上重要的兰花切花品种之一，适合于家庭居室和办公室瓶插，也是加工花束、小花篮的高档用花材料。文心兰花朵色彩鲜艳，形似飞翔的金蝶，又似翩翩起舞的舞女。花的构造极为特殊,其花萼萼片大小相等花瓣与背萼也几乎相等或稍大；花的唇瓣通常三裂或大或小，呈提琴状，在中裂片基部有一脊状凸起物，脊上又凸起的小斑点，颇为奇特。', '隐藏的爱、吉祥如意');
INSERT INTO `db_flower` VALUES ('25', '0025', '石斛兰', '9.90', '是秋石斛（DendrobiumPhalaenopsis）中的一个品种。其假鳞茎丛生，圆柱形或稍扁，基部收缩；叶纸质或革质，矩圆形，顶端2圆裂；总状花序，花大、半垂，玫瑰红色、往花蕊处渐呈白色，艳丽多彩，颇为夺目。在欧美常用石斛花朵制作胸花，配上丝石竹和天冬草，真有\"欢迎光临\"之意。至今，广泛用于大型宴会，开幕式剪彩典礼，享受贵宾待遇。在许多国家把石斛作为每年6月19日的\"父亲节之花\"。', '慈爱、勇敢、欢迎、祝福、纯洁、吉祥、幸福');
INSERT INTO `db_flower` VALUES ('26', '0026', '卡罗拉玫瑰', '29.90', '卡罗拉（Carola），切花月季的一个品种，具有鲜红色，高芯卷边大花型等特点。\r\n\r\n卡罗拉（Carola），切花月季。鲜红色，高芯卷边大花型，花\r\n \r\n卡罗拉（植物） \r\n瓣40-45枚，切枝长度70-90㎝，年产量8枝/株，瓶插期8-10天，叶较小，革质，多刺，抗病性强。', '幸福而浪漫的爱情');
INSERT INTO `db_flower` VALUES ('27', '0027', '黑魔术玫瑰', '40.00', '黑魔术，红玫瑰的品种之一，颜色是深红，厚厚的花瓣上黑色中透着红色，红色中又透着黑色，花型规则美观，有种厚厚的绒感，给人以华贵神秘之感。', '温柔的心，深沉高贵的灵魂');
INSERT INTO `db_flower` VALUES ('28', '0028', '大桃红玫瑰', '35.00', '大桃红是来自澳大利亚的植物，花朵约35枚瓣，浅黄色；气味浓郁。', '我已被你触动，有一点点喜欢你');
INSERT INTO `db_flower` VALUES ('29', '0029', '粉佳人玫瑰', '40.00', '粉佳人玫瑰是由国外引进的品种，花型漂亮，浅粉色系，层次感强.', '感动、爱的宣言、铭记于心、初恋、认识你、是我今生最大的庆幸');
INSERT INTO `db_flower` VALUES ('30', '0030', '金香玉玫瑰', '40.00', '金香玉是蔷薇属蔷薇科植物，是云南省花卉技术培训推广中心保存的栽培品种。', '1.爱情：热情真爱，为爱道歉\r\n友情：你我的友情如同金玉一般坚固而珍贵');
INSERT INTO `db_flower` VALUES ('31', '0031', '虎头茉莉', '11.60', '虎头茉莉，是重瓣茉莉的一种，和菊花茉莉、宝珠茉莉有明显区别。花朵很容易变异，正常花朵的花瓣在50瓣以上，叶子为三叶轮生，变异后为4-8叶不等，可能是基因缺陷的原因该品种抗病力很差，容易受病菌侵蚀。培植难度较高可在高温高湿度环境下扦插。', '忠贞、尊敬、清纯、贞洁、质朴、玲珑、迷人。');
INSERT INTO `db_flower` VALUES ('32', '0032', '宝珠茉莉', '17.60', '常绿小灌木或藤本状灌木，高可达1米。枝条细长小枝有棱角，有时有毛，略呈藤本状。单叶对生，光亮，宽卵形或椭圆形，叶脉明显，叶面微皱，叶柄短而向上弯曲，有短柔毛。初夏由叶腋抽出新梢，顶生聚伞花序，顶生或腋生，有花3-9朵，通常三到四朵，花冠白色，极芳香。大多数品种的花期6-10月，由初夏至晚秋开花不绝，落叶型的冬天开花，花期11月—第二年3月', '忠贞、尊敬、清纯、贞洁、质朴、玲珑、迷人。');
INSERT INTO `db_flower` VALUES ('33', '0033', '鸳鸯茉莉', '8.80', '鸳鸯茉莉（Brunfelsia latifolia Benth.）属茄科鸳鸯茉莉属常绿矮灌木，是华北夏季露天摆放和冬季室内布置的优良盆栽花卉。鸳鸯茉莉高50至100厘米，单叶互生，花大多单生，少有数朵聚生的。花冠呈高脚碟状，有浅裂，花期4月至10月，单花开放5天左右。花朵初开为蓝紫色，渐变为雪青色，最后变为白色，由于花开有先后，在同株上能同时见到蓝紫色和白色的花，故又叫双色茉莉，其英文名之意为“昨天、今天、明天”，这形象地描绘出其花色的特殊变化。', '忠贞和贞洁。\r\n在爱情上面，双色茉莉代表着纯洁的真挚的的爱，不虚假，它表示对爱情的坚贞。双色茉莉的花语还有个含义就是你是我的。\r\n这个花语其实是比较霸道的。双色茉莉花朵美丽花香也很迷人，两种颜色既是十分特殊的相对，也可以互相调和，这代表的是归属感，宣誓主权，表示你是我的。');
INSERT INTO `db_flower` VALUES ('34', '0034', '紫茉莉', '7.20', '紫茉莉（学名：Mirabilis jalapa L.）：草本，高可达1米。根肥粗，倒圆锥形，黑色或黑褐色。茎直立，圆柱形，多分枝，无毛或疏生细柔毛，节稍膨大。叶片卵形或卵状三角形，全缘，两面均无毛，脉隆起。花常数朵簇生枝端，总苞钟形，长约1厘米，5裂，裂片三角状卵形；花被紫红色、黄色、白色或杂色，高脚碟状，筒部长2-6厘米，檐部直径2.5-3厘米，5浅裂；花午后开放，有香气，次日午前凋萎。瘦果球形，直径5-8毫米，革质，黑色，表面具皱纹；种子胚乳白粉质。花期6-10月，果期8-11月。\r\n原产热带美洲。中国南北各地常栽培，为观赏花卉，有时逸为野生。根、叶可供药用，有清热解毒、活血调经和滋补的功效。种子白粉可去面部癍痣粉刺。', '贞洁、质朴、玲珑、臆测、猜忌、成熟美、胆小、怯懦');
INSERT INTO `db_flower` VALUES ('35', '0035', '希茉莉', '9.90', '希茉莉（学名：hamelia patens），别名醉娇花、希美丽、希茉莉，是一种茜草科长隔木属植物，分布于热带美洲。其在中国南方园林绿化中也有栽培种植。为多年生常绿灌木。植株高2～3米，分枝能力强，树冠广圆形；茎粗壮，红色至黑褐色。叶四枚轮生，长披针形，长15～17厘米，宽5～6厘米，纸质，腹面深绿色，背面灰绿色，叶面较粗糙，全缘；幼枝、幼叶及花梗被短柔毛，淡紫红色。聚伞圆锥花序，顶生，管状花长2.5厘米，橘红色。花期几乎全年，或花期5—10月。全株具白色乳汁。', '忠贞、尊敬、清纯、贞洁、质朴、玲珑、迷人。');
INSERT INTO `db_flower` VALUES ('36', '0036', '金钩吻', '92.90', '金钩吻（Gelsemium sempervirens），又名卡罗莱纳茉莉、黄花茉莉、常绿钩吻、北美钩吻、加罗林素馨、断肠草。为马钱科（Loganiaceae）钩吻属木质常绿藤本观赏植物。原产美国南部至中美洲，是美国南卡罗莱那州的州花。因其轻盈繁盛的小黄花具有茉莉花般的清香而颇受人们喜爱，除可用于阳台观赏外，在江南地区也可作为庭园植被，其小叶对生，小黄花喇叭状，自然花期为10月至翌年4月，单花花期为15至25天。全株含有多种生物碱而有毒（花与嫩叶毒性最强），不可食用，植物汁液对部份人的皮肤有强烈的过敏反应。', '独爱你一人，分离。\r\n\r\n一旦触摸，每天要用心抚摸，用饱含爱情的心，用对待心上人的心。由于自触碰的那那一刻，就把自身的全部都交货了出来，注浆了自身的所有，選择了自身的惟一，绝不会更改，就算有些人有些事见不上哪个自身一个承诺了任何的他，它还要思念断肠而死。固执惟一是它的信念！');
INSERT INTO `db_flower` VALUES ('37', '0037', '金丝茉莉', '10.00', '多年生木本植物，毛细根多生，枝条多分枝而散开的藤条，条长而有点下垂，花开白色，又名银丝茉莉，花浓香，花期5-10月，花期很长，连续开放。', '忠贞、尊敬、清纯、贞洁、质朴、玲珑、迷人。');
INSERT INTO `db_flower` VALUES ('38', '0038', '非洲茉莉', '50.00', '非洲茉莉原产于我国南部及东南亚等国, 为马钱科灰莉属常绿 (攀援) 灌木或小乔木, 原名华灰莉木, 别名灰莉木、箐黄果等。它与木樨科的茉莉相似之处就是叶片对生、花有香味。由于灰莉木的谐音与茉莉相似, 也为了使名字好听, 便于销售, 所以花商给它起个新名字“非洲茉莉”。', '朴素自然，清净纯洁。');
INSERT INTO `db_flower` VALUES ('39', '0039', '毛茉莉', '19.90', '毛茉莉（学名：Jasminum multiflorum (Burm. f.) Andr.）原产印度。毛茉莉花朵洁白、馨香，香气犹如茉莉花，花期长，且于冬、春少花季节开放，宜盆栽室内装饰。\r\n毛茉莉为印度尼西亚国花。分布于印度、东南亚以及中国大陆，生长于海拔1000米的地区。主治下痢腹痛，目赤肿痛，疮疡肿毒等病症；花白味香，可作观赏植物。', '纯洁，热情');
INSERT INTO `db_flower` VALUES ('40', '0040', '龙王球', '8.00', '龙王球（学名：Thelocactus setispinus (Engelm.) E.F. Anderson）是仙人掌科瘤玉属植物。茎球形至短圆筒形，高15-30厘米，径8-12厘米，浓绿色，顶部凸起，13棱，棱脊高白色带褐晕，刺座排列密。花冠漏斗状，着生茎顶部，花多数，长5-7.5厘米，径6-8厘米，外瓣黄绿色，先端有红晕，内瓣鲜黄色，基部红色，芳香。花期5-7月。果近圆形，红色，能保持到翌年。 [1]  \r\n原产于美国得克萨斯州南部至墨西哥北部。喜阳光充足，通风良好。 [1]  生命力很强。冬季能耐0℃低温。如温度适合，全年可生长。对土质要求不严。 [2]  \r\n龙王球浓绿茎上具白色带褐晕的波状棱条与多数钩刺，姿态奇异，花大色艳而芳香，既可观茎又可赏花，为仙人掌类的佳品。', '坚强，将爱进行到底.');
INSERT INTO `db_flower` VALUES ('41', '0041', '白檀', '6.50', '白檀，别名小仙人鞭，俗称金牛掌，葫芦拳，仙人掌科白檀属 [1]  。英名称/Peanut Cactus，原产地：阿根廷西部山坡。', '藏在心底的爱');
INSERT INTO `db_flower` VALUES ('42', '0042', '鸾凤玉', '5.80', '鸾凤玉植株球形，老株会形成细长筒状。球体直径10几厘米，有3～9条明显的棱，多数为5棱。棱上的刺座小时候微刺，大了后刺会掉落，刺座上有少量褐色绵毛。球体暗绿色密布比鸾凤玉要大的白色片状毛或小鳞片。鸾凤玉的花朵生在球体顶部的刺座上，花开漏斗形，淡黄色，花径4-5厘米，异花授粉。', '坚强');
INSERT INTO `db_flower` VALUES ('43', '0043', '星兜', '6.80', '星兜，其拉丁学名为Astrophytum asterias。原产美国南部、墨西哥北部、东北和中部地区。植株呈扁圆球形，直径5～8cm，球体由6～10条浅沟而分成6～10个扁圆棱。无刺，刺座上有白色星状绵毛。花着生于球顶部，漏斗形，黄色或红色，花心红色。', '坚强，将爱进行到底.');
INSERT INTO `db_flower` VALUES ('44', '0044', '般若', '6.80', '般若（bān ruò），学名Astrophytum ornatum， 别名美丽星球。属仙人掌科，星球属。多年生草本多浆植物。原产墨西哥。我国引种，各地栽培普遍。为常见、非常美丽的室内盆栽仙人掌类球形种。', '坚强，将爱进行到底.');
INSERT INTO `db_flower` VALUES ('45', '0045', '门廊绒球月季', '59.00', '灌木（德国，HT/切花，奶油/粉，英式，2003）奶油色和浅粉色，浅粉色的中心。花瓣50。花朵平均直径5厘米，小到中等花型，簇花，经典混合茶香，非常勤花，一年四季花开不断，枝条紧凑。成年植株高度50公分到120公分。该品种枝条直立粗壮，抗病性较好，非常适合阳台、露台、庭院种植。', '幸福、荣光、希望。\r\n');
INSERT INTO `db_flower` VALUES ('46', '0046', '龙沙宝石月季', '108.00', '龙沙宝石（Rose Eden） [1]  被玫瑰协会世界联合会的最高奖项评选为：World’s Best Rose（世界最喜欢的玫瑰）。她具备淡雅的颜色和古典的花型，花朵直径7cm至10cm，花瓣数量55-70，花朵香型温和，花朵颜色白粉色，植株大小100-365cm。', '幸福、荣光、希望。');
INSERT INTO `db_flower` VALUES ('47', '0047', '黄金庆典月季', '29.80', '1992年由英国大卫奥斯汀培育，因纪念英国伊丽莎白女王登基四十周年而命名。灌木，重瓣。花金黄色，初期为茶香味，后有酒香味。是英国月季中花朵最大且最为壮观的品种之一。容易栽培和生长，多季节重复开放，株型漂亮丰满，是庆祝和重大场合的首选月季品种。', '遇见最好的自己。');
INSERT INTO `db_flower` VALUES ('48', '0048', '大游行月季', '42.00', '大游行（蔷薇科蔷薇属），是藤本月季的一个品种，主要在中国，湖北、四川和甘肃等省，花朵约33枚瓣，深粉红色。其气味温和，色泽明丽。', '幸福、荣光、希望。');
INSERT INTO `db_flower` VALUES ('49', '0049', '玛格丽特王妃月季', '30.94', '玛格丽特王妃是大卫.奥斯丁培育的藤本月季品种，玛格丽特王妃属于勤花品种，多季持续开花，杏黄色的黄朵、重瓣、花瓣密约120片，花型有些像龙沙宝石，而且带有果香；玛格丽特王妃以其具有独特的颜色与迷人的香味，而受到藤月种植爱好者的欢迎。', '幸福、荣光、希望。');
INSERT INTO `db_flower` VALUES ('50', '0050', '自由精神月季', '39.80', '自由精神月季是一款奥斯丁月季，是一款藤本月季，相对于亚伯体型较大，但是枝条较为直顺，很容易牵引形成花墙的效果。自由精神属于典型的包子花型，即使在炎热的夏季也不会变形。', '幸福、荣光、希望。');
INSERT INTO `db_flower` VALUES ('51', '0051', '鹅掌柴', '96.00', '鹅掌柴，（Schefflera octophylla (Lour.) Harms），为常绿灌木。分枝多，枝条紧密。掌状复叶，小叶5～8枚，长卵圆形，革质，深绿色，有光泽。圆锥状花序，小花淡红色，浆果深红色。是热带、亚热带地区常绿阔叶林常见的植物，原产大洋洲、中国广东、福建、以及南美洲等地的亚热带雨林，日本、越南、印度也有分布。现广泛种植于世界各地。', '自然和谐');
INSERT INTO `db_flower` VALUES ('52', '0052', '昆士兰伞木', '68.00', '昆士兰伞木，吕宋鹅掌柴 [1]  ，称昆石兰遮树，澳洲鸭脚木、方式叶鹅掌柴、伞树、大叶伞。叶片阔大，柔软下垂，形似伞状，株形优雅轻盈，易于管理，适于客厅的墙隅与沙发旁边置放，是室内理想的观叶植物。但目前多由南方引进，成本较高。常绿乔木，高可达30～40米。茎杆直立，少分枝，嫩枝绿色，后呈褐色，平滑。叶为掌状复叶，小叶数随树木的年龄而异，幼年时3～5片，长大时5～7片，至乔木状时可多达16片。小叶片椭圆形，先端钝，有短突尖，叶缘波状，革质，长20～30厘米，宽10厘米，浓绿色叶子。有光泽，叶背淡绿色。叶柄红褐色，长5～10厘米。浆果，圆球形，熟时紫红色。', '遇到你之前世界是一片荒原，遇到你之后世界是一个乐园，过去的岁月对我象一缕轻烟，未来的生命因你而幸福无边！');
INSERT INTO `db_flower` VALUES ('53', '0053', '红掌', '15.80', '又名花烛（Anthurium andraeanum Linden）：是单子叶植物纲天南星科花烛属多年生常绿草本植物。茎节短；叶自基部生出，绿色，革质，全缘，长圆状心形或卵心形。叶柄细长，佛焰苞平出，革质并有蜡质光泽，橙红色或猩红色；肉穗花序黄色，可常年开花不断。\r\n花烛原产于哥斯达黎加、哥伦比亚等热带雨林区。常附生在树上，有时附生在岩石上或直接生长在地上，性喜温暖、潮湿、半阴的环境，忌阳光直射。\r\n花烛花姿奇特美妍。花期持久，适合盆栽、切花或庭园荫蔽处丛植美化。', '大展宏图、热情、热血');
INSERT INTO `db_flower` VALUES ('54', '0054', '金边虎皮兰', '17.80', '金边虎皮兰是一种龙舌兰科虎尾兰属类生物，金边虎皮兰为多年生草本植物。根茎部卷成筒状，叶片抽出时为筒状，随着叶片逐步升高，会渐渐展开平生。分布于非洲热带地区和印度及亚洲南部。', '百纪千岁,万寿无疆');
INSERT INTO `db_flower` VALUES ('55', '0055', '白玉虎皮兰', '15.00', '属龙舌兰科，多年生草本观叶植物，根状茎。叶簇生，肉质线状披针形、硬革质，直立，基部稍呈沟状。', '坚强、忍耐,坚韧不拔');
INSERT INTO `db_flower` VALUES ('56', '0056', '康乃馨', '22.90', '康乃馨，原名：香石竹，拉丁文名：Dianthus caryophyllus.又名：狮头石竹、麝香石竹、大花石竹，拉丁文名：Dianthus caryophyllus L. 石竹科、石竹属多年生草本，高40-70厘米，全株无毛，粉绿色。茎丛生，直立，基部木质化，上部稀疏分枝。叶片线状披针形，顶端长渐尖，基部稍成短鞘，中脉明显，上面下凹，下面稍凸起。花常单生枝端有香气，粉红、紫红或白色；花梗短于花萼；宽卵形，顶端短凸尖，花萼圆筒形，萼齿披针形，边缘膜质；瓣片倒卵形，顶缘具不整齐齿；雄蕊长达喉部；花柱伸出花外。蒴果卵球形，稍短于宿存萼。花期5-8月，果期8-9月。', '爱、魅力、尊敬之情');
INSERT INTO `db_flower` VALUES ('57', '0057', '银星绿萝', '30.00', '银星绿萝，叶肉质状，圆心型或长圆心形，叶端突尖。叶面绒绿，而满银绿色斑块或斑点，叶色清逸美观。', '守望幸福。');
INSERT INTO `db_flower` VALUES ('58', '0058', '心叶蔓绿绒', '88.35', '心叶蔓绿绒（学名：Philodendron hederaceum (Jacq.) Schott）是天南星科喜林芋属植物，多年生草质藤本。株高可达2米。茎草质，多分枝。叶具长柄，心形，全缘，深绿色，革质，叶子长10厘米，宽7.5厘米，有5-7.5厘米长的叶柄。佛焰苞长14厘米；肉穗花序。浆果。 [1-2]  \r\n原产于中美、南美洲，生长在温暖、潮湿的热带雨林中。 [3]  \r\n该种植物热带地区可地栽，用于垂直绿化，温带地区只能盆栽观赏。 [1]  又是很好的空气净化植物之一，可以从大气中去除空气中的毒素，如甲醛，苯和三氯乙烯。', '守望幸福。');
INSERT INTO `db_flower` VALUES ('59', '0059', '巴西三角梅', '25.00', '叶大且厚，深绿无光泽，呈卵圆形，芽心和幼叶呈深红色，枝条硬、直立，茎刺小，花苞片为大红色，花色亮丽，花期为3-5月、9—11月。', '1.热情、坚韧不拔、顽强奋进的精神。\r\n2. 没有真爱是一种悲伤。');
INSERT INTO `db_flower` VALUES ('60', '0060', '乌托邦', '22.89', '属于晚花大花品种，亲本是floridaⅹ未知的大花品种，高度可达2.5-3米，而花朵直径有10-15厘米，花朵呈浅粉色或紫色晕边。\r\n乌托邦的品种特征：日本品种，习性与Clematisflorida近似但更加强健，中到大花，浅粉色花瓣，花瓣顶端及边缘深紫粉色，种植建议：应种在半荫但明亮的位置。\r\n优点：12月还会开花，耐半阴。\r\n缺点：夏季高于35度会停滞生长，不是不耐热，是本性。', '高洁，雅致，贫穷；原谅我，我因你有罪');
INSERT INTO `db_flower` VALUES ('61', '0061', '东方晨曲', '34.23', '东方晨曲铁线莲是属于晚花大花组，花量大呈红紫色，花径可达10-15厘米，高可达3-5米，花期从5月到10月,在盛夏时花量会减少，但很少会不开花，获英国皇家园艺协会花园奖。\r\n　　东方晨曲在向阳的位置种植会有非常好的效果花量繁茂，但花开至第三或第四天起会有些退色，在半遮阴的情况下，能保持花的色泽。冬方晨曲适合盆栽，也可攀爬小乔木或矮灌木，极适宜在阳台或露台大容器栽种，长速中等，每年冬天可重剪。', '高洁，雅致，贫穷；原谅我，我因你有罪');
INSERT INTO `db_flower` VALUES ('62', '0062', '贝蒂夫人', '36.12', '晚花大花型，生长力强，晚夏开花，花深蓝紫色，花蕊奶油黄色。在阳关充沛的地方生长最好，适合在高大的支撑物上生长。', '高洁，雅致，贫穷；原谅我，我因你有罪');
INSERT INTO `db_flower` VALUES ('63', '0063', '格恩西岛', '42.00', '铁线莲格恩西岛（Clematis\'Guernsey Cream\'）是埃维森培育的品种，早花大花型，长势强健，一个非常多花的品种，搭配深色背景种植，效果很好，适合盆栽。\r\n花瓣类型：单瓣，花径：15-22cm，花期：5-11月，5月初为盛花期，株高：2米；', '高洁，雅致，贫穷；原谅我，我因你有罪');
INSERT INTO `db_flower` VALUES ('64', '0064', '金陵凝翠', '180.00', '黄绿色品种，亭亭玉立，无法形容的美。', '娇小玲珑、局促之美，寓意着高洁。');
INSERT INTO `db_flower` VALUES ('65', '0065', '大唐芙蓉', '38.00', '中大型荷花，橙、红色复色，重辨，外辨舌状，内辨细长，辨尖紫红色条纹，基部橙色。初开碗状，盛开叠球状。花辨繁多，繁而有序，端庄大方。莲台正常，黄色。雄蕊正常，附着物乳白色。', '娇小玲珑、局促之美，寓意着高洁。');
INSERT INTO `db_flower` VALUES ('66', '0066', '火花', '6.80', '是碗莲的品种之一。水生植物，是种在盆碗内的微形荷花。叶盾状圆形，叶柄粗壮被短刺；花单生于花梗顶端，花蕾桃型，紫红色。花红色，花径7-8厘米，单瓣型。种植碗莲的容器直径25-750px、深20-625px，用不易渗水的盆钵。生育期需要全光照的环境，在半荫处生长就会表现出强烈的趋光性。\r\n人工培植品种，原产于江苏。中国古籍中多有记载，多用作办公室观赏植物，可以美化工作环境。碗莲娇小玲珑，风姿卓绝，在其花繁叶茂时加以修剪，使之疏密相间，错落有致。如果在盆碗内摆布小山、小船、小桥之类的小品，就能构成令人神往的意境。', '娇小玲珑、局促之美，寓意着高洁。');
INSERT INTO `db_flower` VALUES ('67', '0067', '杏黄', '25.00', '多年生水生草本；根状茎横生，肥厚，节间膨大，内有多数纵行通气孔道，下生须状不定根。叶圆形，盾状，全缘稍呈波状，上面光滑，具白粉，叶柄粗壮，圆柱形，中空。花蕾长桃形，花淡黄--黄绿色，基部娇小玲珑、局促之美，寓意着高洁。黄色。花瓣瘦长，花初开杯状，盛开碟状。\r\n是水生植物，性喜相对稳定的平静浅水、湖沼、泽地、池塘，是其适生地。喜光，生育期需要全光照的环境。荷花极不耐荫，在半荫处生长就会表现出强烈的趋光性。人工培植品种，多用于公园和庭院供观赏。', '娇小玲珑、局促之美，寓意着高洁。');
INSERT INTO `db_flower` VALUES ('68', '0068', '玫红重台', '6.50', '水生植物，是种在盆碗内的微形荷花。叶盾状圆形，叶柄粗壮被短刺；花单生于花梗顶端，花蕾桃型，紫红色。花红色，花径7-9厘米，重台型。花期6-9月。种植碗莲的容器直径25-750px、深20-625px，用不易渗水的盆钵。生育期需要全光照的环境，在半荫处生长就会表现出强烈的趋光性。\r\n人工培植品种，原产于江苏。中国古籍中多有记载，多用作办公室观赏植物，可以美化工作环境。碗莲娇小玲珑，风姿卓绝，在其花繁叶茂时加以修剪，使之疏密相间，错落有致。如果在盆碗内摆布小山、小船、小桥之类的小品，就能构成令人神往的意境。', '娇小玲珑、局促之美，寓意着高洁。');
INSERT INTO `db_flower` VALUES ('69', '0069', '青莲姑娘', '1.50', '是碗莲的品种之一。水生植物，是种在盆碗内的微形荷花。叶盾状圆形，叶柄粗壮被短刺；花单生于花梗顶端，花蕾桃型，紫红色。花红色，花径10厘米左右，重瓣型，着花较多。种植碗莲的容器直径25-750px、深20-625px，用不易渗水的盆钵。生育期需要全光照的环境，在半荫处生长就会表现出强烈的趋光性。', '娇小玲珑、局促之美，寓意着高洁。');
INSERT INTO `db_flower` VALUES ('70', '0070', '小舞妃', '1.00', '多年生水生草本；根状茎横生，肥厚，节间膨大，内有多数纵行通气孔道，下生须状不定根。叶圆形，盾状，全缘稍呈波状，上面光滑，具白粉，叶柄粗壮，圆柱形，中空。花蕾长桃型，黄-白-红色，基部淡黄色,中部白色，尖端淡紫色，单瓣型，花径16-20厘米，着花较多。', '娇小玲珑、局促之美，寓意着高洁。');
INSERT INTO `db_flower` VALUES ('71', '0071', '羊城碗莲', '2.50', '水生植物，是种在盆碗内的微形荷花。叶盾状圆形，叶柄粗壮被短刺；花单生于花梗顶端，花蕾桃形，紫红色，重瓣型，开花较多，花径8-10厘米。种植碗莲的容器直径25-750px、深20-625px，用不易渗水的盆钵。生育期需要全光照的环境，在半荫处生长就会表现出强烈的趋光性。', '娇小玲珑、局促之美，寓意着高洁。');
INSERT INTO `db_flower` VALUES ('72', '0072', '白雪公主', '3.20', '水生植物，是种在盆碗内的微形荷花。叶盾状圆形，叶柄粗壮被短刺；花单生于花梗顶端，花蕾桃型，绿白色。重瓣型。种植碗莲的容器直径25-750px、深20-625px，用不易渗水的盆钵。生育期需要全光照的环境，在半荫处生长就会表现出强烈的趋光性。', '娇小玲珑、局促之美，寓意着高洁。');
INSERT INTO `db_flower` VALUES ('73', '0073', '矮文竹', '29.00', '矮文竹（学名：Asparagus setaceus(Kunth) Jessop cv. Nanus）根状茎粗短，密生稍肉质的细长须根。\r\n百合科天门冬属蔓性常绿亚灌木。根部稍肉质。茎细，圆柱形．绿色，丛生多分枝。叶状枝纤细，6～12枚两侧水平簇生，整个叶状枝平展呈羽毛状。形鳞片状，主茎上鳞片叶多呈刺状。花小，白色，两性，有香气，1-4朵生于短柄上。浆果球形，成熟时黑紫色，内有种子1-3粒。', '婚姻爱情的甜蜜长久，纯洁的友谊长久、长辈福寿永存。');
INSERT INTO `db_flower` VALUES ('74', '0074', '大文竹', '30.18', '攀援植物，高可达3-6米。植株健壮，整片叶状枝较文竹的长，小叶状枝较短且排列不规则。', '婚姻爱情的甜蜜长久，纯洁的友谊长久、长辈福寿永存。');
INSERT INTO `db_flower` VALUES ('75', '0075', '细叶文竹', '36.80', '叶状枝细而长，淡绿色，具白粉。浆果鲜红色。', '婚姻爱情的甜蜜长久，纯洁的友谊长久、长辈福寿永存。');

-- ----------------------------
-- Table structure for `db_order`
-- ----------------------------
DROP TABLE IF EXISTS `db_order`;
CREATE TABLE `db_order` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '订单id',
  `user_id` int(11) NOT NULL,
  `date` datetime NOT NULL,
  `status` varchar(10) NOT NULL,
  `total` double(9,2) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

-- ----------------------------
-- Records of db_order
-- ----------------------------

-- ----------------------------
-- Table structure for `db_user`
-- ----------------------------
DROP TABLE IF EXISTS `db_user`;
CREATE TABLE `db_user` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `username` varchar(32) NOT NULL,
  `password` varchar(32) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8;

